import Link from 'next/link'
import type { Metadata } from 'next'
import PageCol from '@/components/PageCol'
import labSnapshot from '@/data/lab.json'
import { TRACKER, STUDY, PROFICIENCY_STEPS, TrackerStatus, LabSnapshot } from '@/lib/lab'

export const metadata: Metadata = {
  title: 'lab — cyber.dach',
  description:
    'the home lab, live: cluster metrics, services, vms — plus the expansion tracker and the cloud-study curriculum with honest proficiency.',
}

type LabSnapshotData = LabSnapshot

/** hours since the snapshot was regenerated by scripts/fetch-lab.mjs */
function snapshotAgeHours(iso: string) {
  return Math.max(0, (Date.now() - new Date(iso).getTime()) / 36e5)
}

const STATUS_CHIP: Record<TrackerStatus, string> = {
  done: 'chip-done',
  active: 'chip-active',
  planned: 'chip-planned',
}

export default function LabPage() {
  const snap = labSnapshot as LabSnapshotData
  const ageH = snapshotAgeHours(snap.generatedAt)
  const stale = ageH > 24
  const cluster = snap.cluster
  const podsUp = cluster ? cluster.pods.filter(p => p.ready).length : 0
  const trackerDone = TRACKER.filter(t => t.status === 'done').length

  return (
    <PageCol>
      <h1 className="text-2xl font-medium mb-2 stagger-1">lab</h1>
      <p className="text-xs text-[var(--muted)] mb-8 stagger-1">
        the home lab, documented and measured — the tracker records intent, the
        snapshot records reality.
      </p>

      {/* ---- live snapshot ---------------------------------------------------- */}
      <section className="stagger-2 mb-10">
        <div className="flex items-baseline justify-between mb-3">
          <h2 className="sec-label">live snapshot</h2>
          <span className="text-[10px] text-[var(--muted)]">
            {stale && <span aria-hidden>⚠ </span>}
            {snap.cluster || snap.docker
              ? `probed ${snap.generatedAt.slice(0, 10)} (${Math.round(ageH)}h ago)`
              : 'never probed'}
          </span>
        </div>
        {stale && (
          <p className="text-[11px] text-[var(--fg)] border border-[var(--hairline)] rounded-lg px-3 py-2 mb-3">
            this snapshot is over a day old — the lab machine hasn&apos;t published a
            fresher one. run <code>npm run sync:lab</code> where the lab lives.
          </p>
        )}

        <div className="lab-grid mb-3">
          <div className="hud-panel p-3">
            <p className="hud-label mb-1">cluster</p>
            {cluster ? (
              <>
                <p className="text-[13px] font-bold tracking-[-0.02em]">{cluster.context}</p>
                <p className="text-[11px] text-[var(--muted)]">
                  k8s {cluster.version} ·{' '}
                  {cluster.nodes.map(n => `${n.name} ${n.ready ? 'ready' : 'not ready'}`).join(', ')}
                </p>
              </>
            ) : (
              <p className="text-[13px] text-[var(--muted)]">unreachable at last probe</p>
            )}
          </div>
          <div className="hud-panel p-3">
            <p className="hud-label mb-1">pods</p>
            {cluster ? (
              <p className="text-[13px] font-bold tracking-[-0.02em]">
                {podsUp}
                <span className="text-[var(--muted)] font-normal"> / {cluster.pods.length} ready</span>
              </p>
            ) : (
              <p className="text-[13px] text-[var(--muted)]">—</p>
            )}
            <p className="text-[11px] text-[var(--muted)]">
              {cluster ? `${cluster.restartsTotal} restarts (lifetime)` : ''}
            </p>
          </div>
          <div className="hud-panel p-3">
            <p className="hud-label mb-1">forge</p>
            <p className="text-[13px] font-bold tracking-[-0.02em]">
              {snap.services.forgejo.up ? 'up' : 'down'}
            </p>
            <p className="text-[11px] text-[var(--muted)] truncate">{snap.services.forgejo.url}</p>
          </div>
          <div className="hud-panel p-3">
            <p className="hud-label mb-1">vms</p>
            {snap.vms ? (
              <>
                <p className="text-[13px] font-bold tracking-[-0.02em]">
                  {[snap.vms.ubuntu.up && 'ubuntu', snap.vms.kali.up && 'kali'].filter(Boolean).join(' · ') ||
                    'none up'}
                </p>
                <p className="text-[11px] text-[var(--muted)]">
                  ssh fwd {snap.vms.ubuntu.forward} / {snap.vms.kali.forward}
                </p>
              </>
            ) : (
              <p className="text-[13px] text-[var(--muted)]">—</p>
            )}
          </div>
        </div>

        {cluster && (
          <div className="hud-panel p-3">
            <p className="hud-label mb-2">deployments</p>
            <div className="lab-table">
              {cluster.deployments.map(d => (
                <div key={`${d.ns}/${d.name}`} className="lab-row">
                  <span className="text-[10px] text-[var(--muted)] w-24 shrink-0">{d.ns}</span>
                  <span className="text-[12px] flex-1 min-w-0 truncate">{d.name}</span>
                  <span
                    className={`text-[10px] font-bold tabular-nums ${
                      d.ready.startsWith('0/') && !d.ready.startsWith('0/0')
                        ? 'text-[var(--red)]'
                        : 'text-[var(--muted)]'
                    }`}
                  >
                    {d.ready}
                  </span>
                </div>
              ))}
            </div>
          </div>
        )}
        {cluster?.metrics && (
          <p className="text-[10px] text-[var(--muted)] mt-2">
            {cluster.metrics
              .map(m => `${m.name}: cpu ${m.cpu} · mem ${m.mem}`)
              .join('  ·  ')}
          </p>
        )}
      </section>

      {/* ---- network in one glance ------------------------------------------- */}
      <section className="stagger-2 mb-10">
        <h2 className="sec-label mb-3">the network, in one glance</h2>
        <div className="hud-panel p-3">
          <div className="lab-table">
            {[
              ['kind node', 'lab02-control-plane · api 6443 · nodeport 30080 → host 8080'],
              ['three-tiers', 'web nodeport · api + postgres clusterip only (deliberately unpublished)'],
              ['observe', 'prometheus 9090 · grafana 80 · ksm 8080 · exporter 9187 — port-forward only'],
              ['forge', 'forgejo + registry + runner on the cluster, tls by cert-manager, host edge :8443'],
              ['lab-04', 'own docker bridge 172.19/16 — only nginx publishes (host 8081)'],
              ['vms', 'qemu slirp nat · ubuntu 127.0.0.1:50022 · kali 127.0.0.1:50122 · separate nats, no route between them'],
              ['exposure', 'nothing faces the internet — every listener is loopback or private'],
            ].map(([k, v]) => (
              <div key={k} className="lab-row">
                <span className="text-[10px] uppercase tracking-widest text-[var(--muted)] w-24 shrink-0 pt-0.5">
                  {k}
                </span>
                <span className="text-[12px] flex-1 min-w-0">{v}</span>
              </div>
            ))}
          </div>
        </div>
        <p className="text-[11px] text-[var(--muted)] mt-2">
          the full map — addresses, ports, and the who-can-reach-whom matrix — lives in
          the workspace <code>home-lab/network.md</code>.
        </p>
      </section>

      {/* ---- expansion tracker ------------------------------------------------ */}
      <section className="stagger-3 mb-10">
        <div className="flex items-baseline justify-between mb-3">
          <h2 className="sec-label">expansion tracker</h2>
          <span className="text-[10px] text-[var(--muted)]">
            {trackerDone} / {TRACKER.length} complete
          </span>
        </div>
        <div className="lab-meter mb-4" aria-hidden="true">
          <span style={{ width: `${(trackerDone / TRACKER.length) * 100}%` }} />
        </div>
        <div className="space-y-2.5">
          {TRACKER.map(item => (
            <div key={item.name} className="hud-panel p-3">
              <div className="flex items-baseline gap-2">
                <span className={`tracker-chip ${STATUS_CHIP[item.status]}`}>{item.status}</span>
                <span className="text-[13px] font-bold tracking-[-0.02em] flex-1 min-w-0">
                  {item.name}
                </span>
                {item.at && (
                  <span className="text-[10px] text-[var(--muted)] whitespace-nowrap">{item.at}</span>
                )}
              </div>
              <p className="text-[12px] text-[var(--muted)] leading-relaxed mt-1">{item.note}</p>
            </div>
          ))}
        </div>
      </section>

      {/* ---- study curriculum -------------------------------------------------- */}
      <section className="stagger-4 mb-6">
        <h2 className="sec-label mb-1">the study</h2>
        <p className="text-xs text-[var(--muted)] mb-4">
          cloud topics in progress — progress is the fraction of the topic worked
          through, proficiency is the honest self-grade (learning → working →
          comfortable), evidenced by what actually ran.
        </p>
        <div className="space-y-2.5">
          {STUDY.map(s => (
            <div key={s.name} className="hud-panel p-3">
              <div className="flex items-baseline justify-between gap-2 mb-1.5">
                <span className="text-[13px] font-bold tracking-[-0.02em]">{s.name}</span>
                <span className="flex items-center gap-0.5" aria-label={`proficiency: ${s.proficiency}`}>
                  {PROFICIENCY_STEPS.map(step => (
                    <span
                      key={step}
                      className={`prof-step ${step === s.proficiency ? 'on' : ''}`}
                      title={step}
                    />
                  ))}
                  <span className="text-[10px] text-[var(--muted)] ml-1.5">{s.proficiency}</span>
                </span>
              </div>
              <div className="lab-meter mb-2" aria-hidden="true">
                <span style={{ width: `${(s.progress / 3) * 100}%` }} />
              </div>
              <p className="text-[12px] text-[var(--muted)] leading-relaxed">{s.evidence}</p>
            </div>
          ))}
        </div>
        <p className="text-xs text-[var(--muted)] mt-6">
          the write-ups of these labs are under{' '}
          <Link href="/blog" className="underline-link font-medium text-[var(--fg)]">
            blog
          </Link>{' '}
          — the whole arc is{' '}
          <Link href="/blog/from-compose-to-certificates/" className="underline-link font-medium text-[var(--fg)]">
            from a compose file to a certificate chain
          </Link>
          .
        </p>
      </section>
    </PageCol>
  )
}
